<script>(function(){var iframe=document.getElementById('app-iframe');if(!iframe)return;function fb(t){var a=document.createElement('textarea');a.value=t;a.setAttribute('readonly','');a.style.cssText='position:fixed;left:-9999px;top:0;opacity:0';document.body.appendChild(a);a.focus();a.select();try{document.execCommand('copy')}catch(e){}a.remove()}function write(t){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).catch(function(){fb(t)})}else{fb(t)}}function focusFrame(){try{iframe.focus()}catch(e){}try{iframe.contentWindow&&iframe.contentWindow.focus()}catch(e){}}iframe.addEventListener('load',focusFrame);['pointerdown','pointerenter'].forEach(function(ev){iframe.addEventListener(ev,focusFrame)});window.addEventListener('message',function(e){var d=e.data;if(!d||d.type!=='appdashboard-clipboard-write'||typeof d.text!=='string')return;write(d.text)})})();</script>
